/// <summary>
/// The parent class of all the classes to provide data for the receive order page.
/// </summary>
abstract class MobReceiveOrderType extends MobOrder implements TFMOrderTypeInterface
{
    InventDim       itemInventDim;

}

Method.Source:
public static TFMOrderListResponseElement generateResponse(TFMRequestFiltersElement _filters, str _scannedValue)
{
    ListEnumerator				lEnum           = new DictClass(className2Id(classStr(MobReceiveOrderType))).extendedBy(true).getEnumerator();
    MobReceiveOrderType			typeCls;
    DictClass					dc;
    Map							returnMap = new Map(Types::string, Types::Record);
    MapEnumerator				mEnum;
    int							i = 1;
    TFMOrderTypes               orderType = _filters.parmTfmOrderTypes();
    TFMTableNameAttribute       TableName;
    TFMOrderListResponseElement	response = TFMOrderListResponseElement::Construct(MobConstants::Receive());
    while (lEnum.moveNext())
    {

        dc = new DictClass(lEnum.current());
        if (dc == null)
        {
            continue;
        }
        TableName = dc.getAttribute(classStr(TFMTableNameAttribute));
        if (orderType && orderType != TableName.parmTableName() + (TableName.parmOrderType() ? ';'+TableName.parmOrderType() : ''))
        {
            continue;
        }
        if (orderType)
        {
            response.parmPageId(subStr(MobConstants::Receive() + strReplace(orderType,';',''),1,30));
        }
        typeCls = dc.makeObject() as MobReceiveOrderType;
        returnMap = MobHelper::mergeMaps(typeCls.getHeaderRecords(_filters, typeCls.processScannedValue(_scannedValue)), returnMap);

    }
    response.mergeRecordMap(returnMap);

    return response;

}

/// <summary>
/// Method to parse the scanned value, and find the corresponding ID.
/// </summary>
/// <param name = "_scannedValue">The scanned value as a string.</param>
/// <returns>The corresponding ID as a string.</returns>
public ItemId processScannedValue(str _scannedValue)
{
    // The scanned value is assumed to be an item number / barcode
    // Change this code if you want to allow the user scan another value to filter the list of orders
    ItemId              itemId;
    InventItemGTIN      inventItemGTIN;
    InventItemBarcode   inventItemBarcode = InventItemBarcode::findInputBarcode(_scannedValue);
    if (inventItemBarcode && inventItemBarcode.itemId)
    {
        itemId = inventItemBarcode.itemId;
        itemInventDim = inventItemBarcode.inventDim();
    }
    else
    {
        inventItemGTIN = InventItemGTIN::findGTIN(_scannedValue);

        if (inventItemGTIN && inventItemGTIN.itemId)
        {
            itemId = inventItemGTIN.itemId;
            itemInventDim = InventDim::find(inventItemGTIN.inventDimId);
        }
        else if (InventTable::exist(_scannedValue))
        {
            itemId = InventTable::find(_scannedValue).ItemId;
        }
    }

    if (!itemId && _scannedValue)
    {
        throw error(strfmt(InventTable::txtNotExist(),_scannedValue));
    }
    return itemId;
}
